-- Migration 20260825185620 · lane:A1 · writes:evd_event_id_crosswalk · reads:aq_event_map,ticketsdata_event_xref,sg_events_canonical,seatgeek_event_xref,gotickets_event,events · pre:none
-- ============================================================================
-- Migration 20260825185620 — eVenue Desk event-ID crosswalk (evd_event_id_crosswalk)
--
-- Lane:     A1 (data plane / cross-source xref)
-- Touches:  evd_event_id_crosswalk (W); aq_event_map (R), ticketsdata_event_xref (R),
--           sg_events_canonical (R), seatgeek_event_xref (R), gotickets_event (R), events (R)
-- Pre-reqs: none (self-contained table + seed; no cron, no vault secret, no upstream call)
--
-- One row per event seen in the eVenue Desk scans (2026-08-19 / 2026-08-21), keyed by
-- the primary-ticketing source_event_id, carrying that event's id on every resale market
-- we map: Ticket Evolution, GoTickets, SeatGeek, StubHub, Vivid Seats, TickPick,
-- Gametime, Ticketmaster. Shape follows the v_world_cup_2026_all_sources precedent
-- (one id column per source + sources_mapped/_count coverage rollup).
--
-- Mapping is DB-derived and read-only: each Paciolan row is a tenant HOME game, matched
-- to a canonical row by (home team AND opponent present in the event name, opponent
-- preceding home  =>  "<Away> at <Home>") within a +/-1 day window, then hydrated from
-- aq_event_map / ticketsdata_event_xref / gotickets_event / sg_events_canonical.
--
-- TWO PROVENANCE LANDMINES ARE ALREADY APPLIED TO THIS SEED - do not "fix" them back:
--   1. ticketsdata_event_xref.event_id equals the TEvo id on a majority of GT/TM/TP rows
--      (GT 1304/1864, TM 1326/1849, TP 1210/1467) - those are placeholder seeds, NOT
--      platform-native ids. Rows where event_id = tevo_event_id were dropped, which is
--      why gametime_event_id / tickpick_event_id are empty for this event set.
--   2. aq_event_map.tm_event_id is heterogeneous: 56 rows are true hex-derived
--      Ticketmaster ids (> 1e15), 1293 are the TEvo id aliased in (dropped here), and
--      3794 are TicketsData-normalised numeric TM ids (kept - same 4.5M-4.9M namespace
--      the TD xref uses for genuine TM rows).
--
-- Coverage of the 145 seeded rows: SeatGeek 58, Vivid 56, StubHub 55, Ticketmaster 47,
-- GoTickets 17, Ticket Evolution 14, TickPick 0, Gametime 0; 72 rows carry >= 1 id.
--
-- TickPick/Gametime stay 0 after a live pull round (2026-08-25), and NOT for quota reasons.
-- TicketsData /match is their only source; the account is healthy (1,463/2,000 reports and
-- 132,392/250,000 credits at the time of the run, confirmed inside the /match response body).
-- Two independent /match calls at match_confidence 100.0 - one MLB (Cardinals at Phillies,
-- req 9116503) and one NCAA with the venue correctly resolved to Acrisure Stadium (Miami OH
-- at Pittsburgh, req 9121752) - each returned a `matches` object containing ONLY `seatgeek`.
-- The cross-market resolver has no TickPick/Gametime counterpart for this event set, so
-- spending the remaining reports on the other ~18 slug-URL rows has a demonstrated null yield.
-- Two operational notes for whoever retries: /match must be fired strictly ONE at a time
-- (three fired concurrently returned 200/429/429), and a constructed seatgeek.com/e/events/<id>
-- URL is rejected with 500 "could not resolve performer cluster" - it needs the stored slug
-- URL, which sg_events_canonical carries for only 21 of the 58 SG-mapped rows.
-- The 73 unmapped rows are Group-of-5 / FCS home games (Glass Bowl, Yulman, Brooks,
-- Gesa, Canvas, Centreville, Houck, Homer Bryce ...) that are absent from every event
-- universe in this database - they need upstream discovery, not a better matcher.
--
-- Backend-only: RLS on with a service_role policy, anon/authenticated REVOKEd.
-- Idempotent: CREATE TABLE IF NOT EXISTS + INSERT ... ON CONFLICT DO UPDATE.
-- Applied to production 2026-08-25 (operator-authorised this session); re-running is a no-op.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.evd_event_id_crosswalk (
  event_uid              uuid        PRIMARY KEY,
  platform               text        NOT NULL,
  source_event_id        text        NOT NULL,
  id_scheme              text,
  acct                   text,
  season                 text,
  item                   text,
  school_host            text,
  event_name             text,
  opponent               text,
  event_date             date,
  event_time             text,
  venue                  text,
  -- canonical anchor
  aq_short_event_id      text,
  -- one column per resale market
  tevo_event_id          bigint,
  gotickets_event_id     bigint,
  seatgeek_event_id      bigint,
  stubhub_event_id       bigint,
  vividseats_event_id    bigint,
  tickpick_event_id      bigint,
  gametime_event_id      bigint,
  ticketmaster_event_id  bigint,
  -- coverage rollup
  sources_mapped         text[]      NOT NULL DEFAULT '{}',
  sources_mapped_count   integer     NOT NULL DEFAULT 0,
  match_method           text,
  mapped_at              timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT evd_crosswalk_source_uniq UNIQUE (platform, source_event_id)
);

COMMENT ON TABLE public.evd_event_id_crosswalk IS
  'eVenue Desk event-ID crosswalk: one row per primary-ticketing event (Paciolan / ProVenue / Ticketmaster-LVGP / Ticketmaster-web) with its event id on every resale market we map. sources_mapped/_count expose per-event coverage; match_method records how the canonical row was found. Backend-only. A1, mig 20260825185620.';
COMMENT ON COLUMN public.evd_event_id_crosswalk.source_event_id IS
  'The primary-ticketing id in its native scheme (paciolan acct:season:item, provenue pv:org:perf, tm-lvgp tmlvgp:org:code, tm-web tmw:venue:tmid) - see id_scheme.';
COMMENT ON COLUMN public.evd_event_id_crosswalk.aq_short_event_id IS
  'Canonical anchor into aq_event_map (7-char). NULL when no canonical row exists for this event.';
COMMENT ON COLUMN public.evd_event_id_crosswalk.gametime_event_id IS
  'Gametime (GT) platform-native id. Empty across this seed: every GT row available for these events had ticketsdata_event_xref.event_id = tevo_event_id (a placeholder seed, not a Gametime id).';
COMMENT ON COLUMN public.evd_event_id_crosswalk.ticketmaster_event_id IS
  'Ticketmaster id in the TicketsData-normalised numeric namespace, or the hex-derived bigint where one exists. Rows where aq_event_map.tm_event_id merely aliased the TEvo id were dropped.';

CREATE INDEX IF NOT EXISTS idx_evd_crosswalk_aq    ON public.evd_event_id_crosswalk (aq_short_event_id) WHERE aq_short_event_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_evd_crosswalk_tevo  ON public.evd_event_id_crosswalk (tevo_event_id)     WHERE tevo_event_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_evd_crosswalk_sg    ON public.evd_event_id_crosswalk (seatgeek_event_id) WHERE seatgeek_event_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_evd_crosswalk_date  ON public.evd_event_id_crosswalk (event_date);
CREATE INDEX IF NOT EXISTS idx_evd_crosswalk_host  ON public.evd_event_id_crosswalk (school_host);

ALTER TABLE public.evd_event_id_crosswalk ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.evd_event_id_crosswalk FROM anon, authenticated;
DROP POLICY IF EXISTS evd_event_id_crosswalk_service_only ON public.evd_event_id_crosswalk;
CREATE POLICY evd_event_id_crosswalk_service_only
  ON public.evd_event_id_crosswalk FOR ALL TO service_role USING (true) WITH CHECK (true);

INSERT INTO public.evd_event_id_crosswalk
